-- Items: everything that is stocked, grouped in categories, with their yield history.
-- Ids are UUIDs generated by the service (other services will reference items by id).
-- Names are unique ignoring case. Nothing is deleted: rows are inactivated.

CREATE TABLE item_category (
    id         UUID         PRIMARY KEY,
    name       VARCHAR(60)  NOT NULL,
    active     BOOLEAN      NOT NULL DEFAULT TRUE,
    created_by VARCHAR(100) NOT NULL,
    created_at TIMESTAMPTZ  NOT NULL,
    updated_by VARCHAR(100),
    updated_at TIMESTAMPTZ
);
CREATE UNIQUE INDEX item_category_name_uk ON item_category (lower(name));

-- The kind and the stock unit never change: the kardex is kept in that unit.
-- Quantities in the stock unit, NUMERIC(15, 3): up to 12 integer digits and 3 decimals.
CREATE TABLE item (
    id             UUID           PRIMARY KEY,
    name           VARCHAR(80)    NOT NULL,
    kind           VARCHAR(10)    NOT NULL CHECK (kind IN ('PURCHASED', 'PREPARED')),
    category_id    UUID           NOT NULL REFERENCES item_category (id),
    stock_unit     VARCHAR(20)    NOT NULL REFERENCES unit (code),
    minimum_stock  NUMERIC(15, 3) NOT NULL CHECK (minimum_stock >= 0),
    grams_per_unit NUMERIC(15, 3) CHECK (grams_per_unit > 0),
    yield_percent  NUMERIC(5, 2)  NOT NULL DEFAULT 100 CHECK (yield_percent > 0 AND yield_percent <= 100),
    active         BOOLEAN        NOT NULL DEFAULT TRUE,
    created_by     VARCHAR(100)   NOT NULL,
    created_at     TIMESTAMPTZ    NOT NULL,
    updated_by     VARCHAR(100),
    updated_at     TIMESTAMPTZ
);
CREATE UNIQUE INDEX item_name_uk ON item (lower(name));
CREATE INDEX item_category_idx ON item (category_id);

-- Yield measurements: only added. The newest is the current one (copied to item.yield_percent).
CREATE TABLE item_yield (
    id              UUID           PRIMARY KEY,
    item_id         UUID           NOT NULL REFERENCES item (id),
    gross_quantity  NUMERIC(15, 3) NOT NULL CHECK (gross_quantity > 0),
    usable_quantity NUMERIC(15, 3) NOT NULL CHECK (usable_quantity > 0 AND usable_quantity <= gross_quantity),
    yield_percent   NUMERIC(5, 2)  NOT NULL CHECK (yield_percent > 0 AND yield_percent <= 100),
    note            VARCHAR(200),
    created_by      VARCHAR(100)   NOT NULL,
    created_at      TIMESTAMPTZ    NOT NULL
);
CREATE INDEX item_yield_item_idx ON item_yield (item_id, created_at DESC);
